//! The build half of the runtime route: three modules and one generated file.
//!
//! An SDK that ships the runtime route calls `createModule` in place of
//! `translate.createModule()` and imports what comes back as its `c` module.
//! Nothing here links the bridge library. That is the point: in this
//! configuration the symbols arrive through the platform loader at run time,
//! and linking the archive as well would make the linker demand them before
//! `load` ever runs.
//!
//!   rt        runtime/loader.zig, the reusable core. Pure Zig; imported by the
//!             facade in both configurations, because `LoadSource` and
//!             `LoadError` are this SDK's public types and must be the same
//!             types whichever configuration is built.
//!   library   runtime/library.zig, this SDK's descriptor: the namespaced
//!             synchronization binding and the one load-time check.
//!   dispatch  generated by runtime/generate.zig from the real translation
//!             output: the table, the wrappers, `load`, and the re-exported
//!             translated namespace. It imports `rt`, `library` and the
//!             generator's patched translation as `c_native`, which imports the
//!             dispatch back as `c_routed`.
//!   sync.c    compiled into the dispatch with
//!             `-DRT_SYNC_PREFIX=random123_rt`, so its symbols cannot collide
//!             with another SDK's.
//!
//! ## The one thing a caller must not do
//!
//! Do not link the compiled bridge into a module that imports this dispatch.
//! The facade's `c` import is the dispatch, and nothing else in the graph
//! should reference `librandom123`, or the linker resolves the symbols
//! statically and the runtime route silently becomes a linked one.
//!
//! ## What the provider is, in one paragraph
//!
//! Random123 upstream is header-only: every algorithm is `static __inline__` and
//! every default-round entry point is a macro, so no upstream file produces a
//! linkable symbol. What this route loads is therefore this fork's own bridge
//! library, compiled from `zig/bridge/random123_bridge.c` over the real upstream
//! headers, and a provider is that artifact built as a shared object. That is
//! the whole candidate set: there is no upstream binary to load and no system
//! library this package could bind to instead.
const std = @import("std");

/// The prefix `runtime/sync.c` is compiled with.
///
/// `runtime/library.zig` declares the same prefix in the symbol names it binds.
/// The two must agree, and a build where they do not fails to link, which is
/// the whole error report: there is no runtime path that could hide it.
///
/// A build that needs a second, independent instance of this SDK in one binary
/// should change this value *and* the prefix in `runtime/library.zig`, and then
/// give the second instance its own copy of both files. Nothing else in the
/// package assumes one instance.
const sync_prefix = "random123_rt";

/// `extern` declarations that the C library provides and that must therefore
/// stay direct.
///
/// `zig/bridge/random123_bridge.h` includes exactly two headers: `<stdint.h>`
/// (`random123_bridge.h:27`), which declares no function, and
/// `<Random123/array.h>` (`random123_bridge.h:29`). That one reaches
/// `features/compilerfeatures.h`, which reaches the compiler's own features
/// header -- `gccfeatures.h` for every compiler this package builds with --
/// and `features/gccfeatures.h:67-70` defines `R123_ASSERT` by including
/// `<assert.h>`.
///
/// That is the whole of the C-library surface this translation can reach, and
/// it is three declarations. The names below are every spelling `<assert.h>`
/// uses for the failure function across the C libraries these targets link:
/// glibc's two-argument `__assert_fail`, its POSIX-errno sibling
/// `__assert_perror_fail`, the bare `__assert` that older glibc `<assert.h>`
/// macros expanded to, musl's `__assert_fail`, and the Microsoft CRT's
/// `_assert`. Which of them actually appears depends on the target's libc, and
/// this build cannot enumerate another target's `<assert.h>`. The pinned
/// translator does, and on 2026-10-04 it emitted three more assertion-family
/// names for targets this SDK publishes: OpenBSD's `__assert2`
/// (`generic-openbsd/assert.h:56`), Darwin's `__assert_rtn`
/// (`any-darwin-any/_assert.h:63`) and MinGW's `_wassert`
/// (`any-windows-any/assert.h:24`). MinGW's `<crtdefs.h>` also reaches
/// `<_mingw.h>`, which declares `__mingw_get_crt_info`
/// (`any-windows-any/_mingw.h:665`) and, on an architecture for which the
/// compiler has no `__prefetch` builtin, `__prefetch`
/// (`any-windows-any/_mingw.h:650`). All five are measured, not guessed.
///
/// **Over-listing is inert and under-listing breaks the load.** The generator
/// consults this list per declaration the translation actually produced; a name
/// no header declares is never looked up, while an `extern fn` it does not
/// recognise as C library noise is routed, which makes the *provider*
/// responsible for exporting libc's own assertion failure function. That is
/// missing-symbol at `dlopen` time, on every target, for a name that has
/// nothing to do with Random123.
///
/// No Random123 symbol is in this list: every name the bridge defines begins
/// with `r123_bridge_`.
const libc_noise =
    \\__assert_fail,__assert_perror_fail,__assert,_assert,__assert2,__assert_rtn,_wassert,
    \\__mingw_get_crt_info,__prefetch
;

/// `extern` declarations the provider may legitimately not export.
///
/// This SDK declares none, and the one candidate is deliberately not here.
///
/// The five AES-NI and ARS wrappers sit inside `#if R123_BRIDGE_HAS_AESNI`
/// (`random123_bridge.h:151`), and that macro is one build-wide decision that
/// reaches the bridge compile line and the translation step alike. A build that
/// compiled the wrappers therefore has those five declarations in the header
/// this dispatch is generated from, and a provider without them is a refused
/// provider. Marking them optional would not fix that and would hide it: an
/// `extern` left direct in this configuration has nothing to resolve against,
/// because the whole point of the runtime route is that nothing is linked, so
/// it becomes an undefined symbol at link time rather than a load-time answer.
/// The pairing requirement is written out in `runtime/library.zig`, and the
/// table itself is configuration-aware without a single conditional name here,
/// because it is generated from this build's own translation.
const provider_optional = "";

/// `extern` declarations this build does not require a provider to export.
///
/// None. Every `r123_bridge_*` function the header declares is expected from a
/// provider, and a provider that does not export one of them is refused rather
/// than half used.
///
/// A name here is routed and optional rather than direct; only `libc_noise`
/// above stays direct.
const provider_excluded = "";

/// The loader core, for a *linked* build to import.
///
/// A linked build has no dispatch, so the facade needs the core module itself
/// for the two public types `LoadSource` and `LoadError`: they are this SDK's
/// types and they must be the same types a caller names in either
/// configuration. It costs a linked build two declarations and no code, since
/// nothing else in that module is referenced until a configuration actually
/// instantiates the loader.
///
/// A runtime-loading build must *not* import this separately: `createModule`
/// makes the one core instance the dispatch uses, and the dispatch re-exports
/// the two types from it. Two instances would be two sets of types, and a
/// consumer would be naming one while `load` expects the other.
pub fn createCoreModule(
    b: *std.Build,
    target: std.Build.ResolvedTarget,
    optimize: std.builtin.OptimizeMode,
) *std.Build.Module {
    return b.createModule(.{
        .root_source_file = b.path("runtime/loader.zig"),
        .target = target,
        .optimize = optimize,
        // The Unix backend calls `dlopen`, which is libc. Nothing in this module
        // is compiled into a linked build, so this costs nothing there.
        .link_libc = true,
    });
}

/// The runtime-loaded `c` module for one target.
///
/// `translate` is the translation step for that same target and configuration;
/// its output is read by the generator, so the dispatch describes the header
/// this build actually selected rather than another one. In particular the
/// dispatch's table carries the AES-NI and ARS entries exactly when this
/// build's own `-Daesni` decision put those declarations in the header, which
/// is what keeps the two configurations from needing two bridges.
pub fn createModule(
    b: *std.Build,
    translate: *std.Build.Step.TranslateC,
    target: std.Build.ResolvedTarget,
    optimize: std.builtin.OptimizeMode,
) *std.Build.Module {
    const core = createCoreModule(b, target, optimize);

    const library = b.createModule(.{
        .root_source_file = b.path("runtime/library.zig"),
        .target = target,
        .optimize = optimize,
    });
    library.addImport("rt", core);

    return createDispatchModule(b, translate, target, optimize, core, library);
}

const GeneratedSources = struct {
    native: std.Build.LazyPath,
    dispatch: std.Build.LazyPath,
};

fn createDispatchModule(
    b: *std.Build,
    translate: *std.Build.Step.TranslateC,
    target: std.Build.ResolvedTarget,
    optimize: std.builtin.OptimizeMode,
    core: *std.Build.Module,
    library: *std.Build.Module,
) *std.Build.Module {
    const sources = generateDispatch(b, translate, target);

    const dispatch = b.createModule(.{
        .root_source_file = sources.dispatch,
        .target = target,
        .optimize = optimize,
        .link_libc = true,
    });
    dispatch.addImport("rt", core);
    dispatch.addImport("library", library);
    // The translated header, under a name that says what it is. Every type and
    // constant in the dispatch is re-exported from here rather than restated, so
    // `c.struct_r123array4x32` in a facade and `c_native.struct_r123array4x32`
    // in the dispatch are one type.
    //
    // The root is the generator's *patched* translation, not the raw one the
    // translate step wrote. `const __root = @import("c_routed");` is what makes
    // a macro-expanded struct member that names a bridge function resolve to
    // the routed wrapper rather than escaping to a native `extern` this route
    // never links. That repointing is why the two modules import each other.
    //
    // `b.createModule` rather than `translate.createModule()`, because
    // `translate.createModule()` copies only `link_libc` and `system_libs` off
    // the step, so the include path `zig/bridge/random123_bridge.h` was
    // translated with does not come along.  Nothing here needs it, and the
    // translation is why rather than an assumption about it: `translate-c`
    // flattens what it reads, and this header's output carries no `@cImport`
    // and no `@cInclude` at all.  All thirty-six of its `extern fn` are fully
    // elaborated, the thirty-three `r123_bridge_*` plus the three `<assert.h>`
    // declarations listed in `libc_noise`, and every `r123arrayNxW` counter and
    // key type is already an `extern struct` in the output.  The linked shape
    // does re-add the path, because there the translated module is what a
    // consumer compiles against directly; here it is an implementation detail
    // behind `c_native`.
    const native = b.createModule(.{
        .root_source_file = sources.native,
        .target = target,
        .optimize = optimize,
        .link_libc = true,
    });
    native.addImport("c_routed", dispatch);
    dispatch.addImport("c_native", native);
    dispatch.addCSourceFiles(.{
        .files = &.{"runtime/sync.c"},
        .flags = &.{b.fmt("-DRT_SYNC_PREFIX={s}", .{sync_prefix})},
        .language = .c,
    });
    return dispatch;
}

/// Runs the generator over the translation step's real output.
///
/// The generator is a host program built and run by this build, so the dispatch
/// is produced for the target being built from that target's own translation.
/// Nothing is cached across configurations: a different `-Daesni` decision
/// produces a different translation step output, which produces a different
/// dispatch.
fn generateDispatch(
    b: *std.Build,
    translate: *std.Build.Step.TranslateC,
    target: std.Build.ResolvedTarget,
) GeneratedSources {
    const generator = b.addExecutable(.{
        .name = b.fmt("random123-runtime-generate-{s}", .{
            target.result.zigTriple(b.allocator) catch @panic("unspellable target"),
        }),
        .root_module = b.createModule(.{
            .root_source_file = b.path("runtime/generate.zig"),
            .target = b.graph.host,
            .optimize = .Debug,
        }),
    });

    const run = b.addRunArtifact(generator);
    run.addArg("--library");
    run.addArg("random123");
    run.addArg("--translate");
    run.addFileArg(translate.getOutput());
    if (libc_noise.len != 0) {
        run.addArg("--noise");
        run.addArg(libc_noise);
    }
    if (provider_optional.len != 0) {
        run.addArg("--optional");
        run.addArg(provider_optional);
    }
    if (provider_excluded.len != 0) {
        run.addArg("--exclude");
        run.addArg(provider_excluded);
    }
    run.addArg("--native-output");
    const native_source = run.addOutputFileArg("native.zig");
    run.addArg("--output");
    const dispatch_source = run.addOutputFileArg("dispatch.zig");
    return .{ .native = native_source, .dispatch = dispatch_source };
}
